    void ZXThemeCleanUp()
    {
        if (iconsTexture)
        {
            glDeleteTextures(1, &iconsTexture);
        }
    }

    bool ZXBegin(const char* name, ImGuiWindowFlags flags)
    {
        const bool result = ImGui::Begin(name, nullptr, flags);

        if (result)
        {
            windowPos = ImGui::GetWindowPos();
            windowPos.x -= 16.0f;

            windowSize = ImGui::GetWindowSize();
            drawList = ImGui::GetWindowDrawList();

            drawList->PushClipRectFullScreen();
            addSpectrumBar(0xffc0c000, 0xffffff00);
            addSpectrumBar(0xff00c000, 0xff00ff00);
            addSpectrumBar(0xff00c0c0, 0xff00ffff);
            addSpectrumBar(0xff0000c0, 0xff0000ff);
            drawList->PopClipRect();
        }

        return result;
    }

    void ZXLabel(const char* name, float width)
    {
        ImGui::AlignTextToFramePadding();
        ImGui::SetNextItemWidth(width);
        ImGui::SetCursorPosX(ImGui::GetCursorPosX() - 10.0f);
        ImGui::LabelText("", name);
    }

    void ZXIcon(ZXIconId id)
    {
        if (!iconsTexture)
        {
            HMODULE hModule = GetModuleHandle(NULL);
            HRSRC hRes = FindResource(hModule, MAKEINTRESOURCE(IDR_ICONS), TEXT("PNG"));
            HGLOBAL hMem = LoadResource(hModule, hRes);
            LPVOID pRes = LockResource(hMem);
            DWORD size = SizeofResource(hModule, hRes);
            int channels;
            unsigned char* iconsImageData = stbi_load_from_memory((const stbi_uc*)pRes, size, &iconsTextureWidth, &iconsTextureHeight, &channels, 4);

            glGenTextures(1, &iconsTexture);
            glBindTexture(GL_TEXTURE_2D, iconsTexture);

            glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
            glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);

            glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
            glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);

            glPixelStorei(GL_UNPACK_ROW_LENGTH, 0);
            glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, iconsTextureWidth, iconsTextureHeight, 0, GL_RGBA, GL_UNSIGNED_BYTE, iconsImageData);
            stbi_image_free(iconsImageData);
        }

        const float x = id % ZX_ICONS_COLUMNS;
        const float y = id / ZX_ICONS_COLUMNS;
        ImGui::SetCursorPosY(ImGui::GetCursorPosY() + 1.0f);
        ImGui::Image(iconsTexture, ImVec2(16.0, 16.0), ImVec2(x * ZX_ICON_WIDTH, y * ZX_ICON_HEIGHT), ImVec2((x + 1) * ZX_ICON_WIDTH, (y + 1) * ZX_ICON_HEIGHT));
        ImGui::SameLine();
        ImGui::SetCursorPos(ImVec2(ImGui::GetCursorPosX() - 5.0f, ImGui::GetCursorPosY() - 1.0f));
    }

    bool ZXCollapsingHeader(const char* name, bool &collapsed)
    {
        ImVec2 posMin = ImGui::GetCursorScreenPos();
        posMin.x -= 20.0f;
        const ImVec2 posMax = ImVec2(posMin.x + ImGui::GetContentRegionAvail().x + 40.0f, posMin.y + 30.0f);
        
        ImGuiContext& g = *GImGui;
        ImGuiWindow* window = g.CurrentWindow;
        const bool isMouseHovering = IsWindowContentHoverable(window) && IsMouseHoveringRect(posMin, posMax);
        drawList = ImGui::GetWindowDrawList();
        drawList->AddRectFilled(posMin, posMax, isMouseHovering ? ImGui::GetColorU32(ImGuiCol_TitleBgActive) : ImGui::GetColorU32(ImGuiCol_TitleBg));
        ImGui::SetCursorPosY(ImGui::GetCursorPosY() + 6.0f);

        ImGui::TextUnformatted(collapsed ? "+" : "-");
        ImGui::SameLine();
        ImGui::SetCursorPosX(32.0f);
        ImGui::TextUnformatted(name);

        ImGui::SetCursorPosY(ImGui::GetCursorPosY() - 4.0f);
        
        if (isMouseHovering && ImGui::IsMouseClicked(ImGuiMouseButton_Left, false))
        {
            collapsed = !collapsed;
        }

        if (!collapsed)
        {
            ImGui::Dummy(ImVec2(0.0f, 0.0f));
        }

        return !collapsed;
    }
